#!/usr/bin/env node
'use strict';
// Generates the Playwright API reference that the Studio prompts carry (ADR-SC-008 D6). The reference is
// guidance for the model, not an allow-list: leaving a member out restricts nothing.
//
//   node tools/build-playwright-reference.cjs           write backend/src/main/resources/studio/playwright-reference/reference.txt
//   node tools/build-playwright-reference.cjs --check   exit 1 unless the committed file equals the generated bytes
//   node tools/build-playwright-reference.cjs --hash    print the sha256 of the generated bytes (the referenceHash)
//
// Input: the pinned playwright-core/playwright type definitions (syntax-only parse, no type checker).
// Output is deterministic: source order, a fixed section order, no timestamps.
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const runner = path.join(root, 'studio-runner');
const OUTPUT = path.join(root, 'backend/src/main/resources/studio/playwright-reference/reference.txt');
const ts = require(path.join(runner, 'node_modules/typescript'));

const CORE_CAP = 20480;
const EXTENDED_CAP = 4096;
const SUMMARY_CAP = 140;

const TYPES = path.join(runner, 'node_modules/playwright-core/types/types.d.ts');
const TEST_TYPES = path.join(runner, 'node_modules/playwright/types/test.d.ts');
// Interface -> how the model reaches it.
const SOURCES = [
  { file: TYPES, receivers: { Page: 'page', Frame: 'frame', Locator: 'locator', FrameLocator: 'frameLocator', Keyboard: 'page.keyboard', Mouse: 'page.mouse', Touchscreen: 'page.touchscreen', BrowserContext: 'context', Dialog: 'dialog', Download: 'download', FileChooser: 'fileChooser' } },
  { file: TEST_TYPES, receivers: { LocatorAssertions: 'expect(locator)', PageAssertions: 'expect(page)', GenericAssertions: 'expect(value)' } },
];
// ADR-SC-008 D3.2: the runner denies these at call time, so the reference does not offer them.
const RUN_INTEGRITY = new Set(['Page.video', 'Page.close', 'BrowserContext.close', 'BrowserContext.browser', 'BrowserContext.newPage', 'BrowserContext.newCDPSession', 'BrowserContext.tracing']);
// Node-side HTTP clients bypass the page and its domain checks (ADR-SC-008 X-2), so they are not suggested to the model.
const NOT_OFFERED = new Set(['Page.request', 'BrowserContext.request']);
// Callback-style registrations: the model waits for events with waitForEvent instead.
const LISTENERS = new Set(['on', 'once', 'addListener', 'removeListener', 'off', 'prependListener', 'removeAllListeners']);
// Page and Frame methods that take a selector string first are twins of the Locator methods.
const TWIN_EXCEPTIONS = new Set(['locator', 'frameLocator']);

// Ordered; the first matching rule wins. A rule is [interface regex, member regex].
const SECTIONS = [
  { id: 'core.locators', tier: 'core', title: 'Locators', rules: [
    ['^(Page|Locator)$', '^(getBy\\w+|locator|frameLocator)$'],
    ['^Locator$', '^(filter|first|last|nth|and|or|contentFrame|describe|count)$'] ] },
  { id: 'core.actions', tier: 'core', title: 'Actions', rules: [
    ['^Locator$', '^(click|dblclick|fill|clear|press|pressSequentially|check|uncheck|setChecked|selectOption|hover|focus|blur|tap|dragTo|scrollIntoViewIfNeeded|selectText)$'],
    ['^Page$', '^(goto|reload|goBack|goForward)$'] ] },
  { id: 'core.assertions', tier: 'core', title: 'Assertions with expect (web-first, retry until the timeout)', rules: [
    ['^LocatorAssertions$', '^(?!toHaveScreenshot$|toMatchAriaSnapshot$).+'],
    ['^PageAssertions$', '^(toHaveTitle|toHaveURL|not)$'] ] },
  { id: 'reads-element', tier: 'extended', title: 'Reading an element', rules: [
    ['^Locator$', '^(textContent|innerText|innerHTML|inputValue|getAttribute|allInnerTexts|allTextContents|all|isVisible|visible|isHidden|isEnabled|isDisabled|isEditable|isChecked|boundingBox|ariaSnapshot|ariaSnapshotJSON|toString|normalize|description|page)$'] ] },
  { id: 'reads-page', tier: 'extended', title: 'Reading the page', rules: [
    ['^(Page|Frame)$', '^(title|url|content|viewportSize|consoleMessages|clearConsoleMessages|pageErrors|clearPageErrors|ariaSnapshot|ariaSnapshotJSON|isClosed|isDetached|name|context)$'] ] },
  { id: 'waits', tier: 'extended', title: 'Waiting', rules: [
    ['^Locator$', '^waitFor$'],
    ['^(Page|Frame)$', '^(waitForLoadState|waitForURL|waitForTimeout)$'],
    ['^(Page|BrowserContext)$', '^waitForEvent$'] ] },
  { id: 'frames', tier: 'extended', title: 'Frames, pages and popups', rules: [
    ['^FrameLocator$', '.*'],
    ['^Frame$', '^(childFrames|parentFrame|frameElement|page)$'],
    ['^Page$', '^(frame|frames|mainFrame|opener|bringToFront)$'],
    ['^BrowserContext$', '^(pages|isClosed)$'] ] },
  { id: 'frame-api', tier: 'extended', title: 'Working inside a Frame object', rules: [
    ['^Frame$', '^(goto|getBy\\w+|locator|frameLocator|dragAndDrop|content|setContent)$'] ] },
  { id: 'dialogs-files', tier: 'extended', title: 'Dialogs, downloads and file inputs', rules: [
    ['^(Dialog|Download|FileChooser)$', '.*'],
    ['^Locator$', '^(setInputFiles|drop)$'] ] },
  { id: 'input-devices', tier: 'extended', title: 'Keyboard, mouse and touch', rules: [
    ['^(Keyboard|Mouse|Touchscreen)$', '.*'],
    ['^Page$', '^(keyboard|mouse|touchscreen|dragAndDrop)$'],
    ['^Locator$', '^dispatchEvent$'] ] },
  { id: 'script', tier: 'extended', title: 'Running script in the page', rules: [
    ['^(Page|Frame|Locator)$', '^(evaluate|evaluateHandle|evaluateAll|waitForFunction)$'] ] },
  { id: 'page-content', tier: 'extended', title: 'Page content, init scripts and handlers', rules: [
    ['^(Page|Frame)$', '^(addScriptTag|addStyleTag|setContent)$'],
    ['^Page$', '^(addLocatorHandler|removeLocatorHandler)$'],
    ['^(Page|BrowserContext)$', '^(exposeBinding|exposeFunction|addInitScript)$'],
    ['^Locator$', '^(elementHandle|elementHandles)$'] ] },
  { id: 'network', tier: 'extended', title: 'Network', rules: [
    ['^(Page|BrowserContext)$', '^(route|routeFromHAR|routeWebSocket|unroute|unrouteAll|setExtraHTTPHeaders)$'],
    ['^Page$', '^(waitForRequest|waitForResponse|requests)$'] ] },
  { id: 'storage', tier: 'extended', title: 'Cookies and storage', rules: [
    ['^BrowserContext$', '^(addCookies|clearCookies|cookies|storageState|setStorageState|credentials|setHTTPCredentials)$'],
    ['^Page$', '^(localStorage|sessionStorage)$'] ] },
  { id: 'environment', tier: 'extended', title: 'Environment, timeouts and evidence', rules: [
    ['^(Page|BrowserContext)$', '^(emulateMedia|setViewportSize|grantPermissions|clearPermissions|setGeolocation|setOffline|setDefaultNavigationTimeout|setDefaultTimeout|clock|debugger|serviceWorkers)$'],
    ['^Page$', '^(screenshot|pdf|pause|pickLocator|cancelPickLocator|hideHighlight|requestGC|workers|coverage|screencast)$'],
    ['^Locator$', '^(screenshot|highlight|hideHighlight)$'] ] },
  { id: 'value-assertions', tier: 'extended', title: 'Value assertions on plain values', rules: [
    ['^GenericAssertions$', '^(not|resolves|rejects|toBe\\w*|toEqual|toStrictEqual)$'] ] },
  { id: 'value-assertions-more', tier: 'extended', title: 'More value assertions and snapshots', rules: [
    ['^GenericAssertions$', '.*'],
    ['^LocatorAssertions$', '^(toHaveScreenshot|toMatchAriaSnapshot)$'],
    ['^PageAssertions$', '^(toHaveScreenshot|toMatchAriaSnapshot)$'] ] },
];

function fail(message) {
  console.error('build-playwright-reference: ' + message);
  process.exit(1);
}

function version(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8')).version;
}

function sha256(buffer) {
  return crypto.createHash('sha256').update(buffer).digest('hex');
}

// ---- parsing (adapted from the registry extractor: JSDoc, parameters, inline option literals) ----

function strip(text) {
  return text.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\s+/g, ' ').trim();
}

function docOf(node) {
  const docs = node.jsDoc || [];
  if (!docs.length) return { text: '', deprecated: false };
  const doc = docs[docs.length - 1];
  const text = typeof doc.comment === 'string' ? doc.comment : (doc.comment || []).map((part) => part.text || '').join('');
  return { text, deprecated: (doc.tags || []).some((tag) => tag.tagName.text === 'deprecated') };
}

function summary(text) {
  const paragraphs = text.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
  while (paragraphs.length > 1 && /^\*\*NOTE\*\*/.test(paragraphs[0])) paragraphs.shift();
  let first = (paragraphs[0] || '').replace(/\*\*Usage\*\*[\s\S]*$/, '').replace(/```[\s\S]*?```/g, '');
  first = first.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/[`*]/g, '').replace(/\s+/g, ' ').trim();
  const sentence = first.match(/^(.+?[.!?])(\s|$)/);
  let result = (sentence ? sentence[1] : first).trim();
  if (result.length > SUMMARY_CAP) result = result.slice(0, SUMMARY_CAP).replace(/\s+\S*$/, '') + '...';
  return result;
}

function memberOf(node, sf, iface) {
  const name = node.name.getText(sf);
  const doc = docOf(node);
  const member = { iface, name, deprecated: doc.deprecated, summary: summary(doc.text), property: ts.isPropertySignature(node) };
  if (member.property) {
    member.type = strip(node.type ? node.type.getText(sf) : 'any');
    return member;
  }
  member.params = node.parameters.map((p) => {
    const type = p.type;
    const options = type && ts.isTypeLiteralNode(type)
      ? type.members.filter(ts.isPropertySignature).filter((o) => !docOf(o).deprecated && o.name.getText(sf) !== 'signal')
          .map((o) => ({ name: o.name.getText(sf), optional: !!o.questionToken, type: strip(o.type ? o.type.getText(sf) : 'any') }))
      : null;
    return { name: p.name.getText(sf), optional: !!p.questionToken || !!p.initializer, rest: !!p.dotDotDotToken, type: strip(type ? type.getText(sf) : 'any'), options };
  });
  member.returns = strip(node.type ? node.type.getText(sf) : 'void').replace(/^Promise<(.*)>$/, '$1');
  return member;
}

function readMembers() {
  const members = [];
  for (const source of SOURCES) {
    const sf = ts.createSourceFile(source.file, fs.readFileSync(source.file, 'utf8'), ts.ScriptTarget.Latest, true);
    sf.forEachChild((node) => {
      if (!ts.isInterfaceDeclaration(node) || !(node.name.text in source.receivers)) return;
      const iface = node.name.text;
      for (const child of node.members) {
        if (!child.name || child.name.getText(sf).startsWith('[')) continue;
        members.push(memberOf(child, sf, iface));
      }
    });
  }
  return members;
}

// ---- selection, grouping and rendering ----

function kept(members) {
  const byKey = new Map();
  for (const member of members) {
    const key = member.iface + '.' + member.name;
    if (member.deprecated || RUN_INTEGRITY.has(key) || NOT_OFFERED.has(key) || LISTENERS.has(member.name)) continue;
    const first = member.params && member.params[0];
    if ((member.iface === 'Page' || member.iface === 'Frame') && first && first.name === 'selector' && !TWIN_EXCEPTIONS.has(member.name)) continue;
    if (!byKey.has(key)) byKey.set(key, []);
    byKey.get(key).push(member);
  }
  return byKey;
}

function sectionOf(iface, name) {
  const matches = SECTIONS.filter((section) => section.rules.some(([i, n]) => new RegExp(i).test(iface) && new RegExp(n).test(name)));
  return matches[0] || null;
}

function receiverOf(iface) {
  for (const source of SOURCES) if (iface in source.receivers) return source.receivers[iface];
  return fail('unknown interface ' + iface);
}

// A long list of string literals (the 80+ ARIA roles) is shown as examples; the model knows the full set.
function shortType(type) {
  const literals = type.match(/^(?:"[^"]*"|'[^']*')(?:\s*\|\s*(?:"[^"]*"|'[^']*'))+$/) ? type.split('|').map((t) => t.trim().replace(/^'(.*)'$/, '"$1"')) : null;
  if (!literals || literals.length <= 8) return type;
  return literals.slice(0, 4).join('|') + '|... (' + literals.length + ' values)';
}

function parameterText(param, tier) {
  let type = param.full ? param.type : shortType(param.type);
  if (param.options) {
    const inner = param.options.map((o) => o.name + (o.optional ? '?' : '') + (tier === 'core' ? '' : ': ' + o.type)).join(', ');
    type = '{ ' + inner + ' }';
  }
  return (param.rest ? '...' : '') + param.name + (param.optional ? '?' : '') + ': ' + type;
}

function lineOf(member, tier, overloadNote) {
  const receiver = receiverOf(member.iface);
  const note = member.summary ? '  # ' + member.summary : '';
  if (member.property) return receiver + '.' + member.name + ': ' + member.type + note;
  const params = member.params.map((p) => parameterText(p, tier)).join(', ');
  return receiver + '.' + member.name + '(' + params + ') -> ' + member.returns + (overloadNote || '') + note;
}

function linesOf(overloads, tier) {
  const first = overloads[0];
  if (first.name === 'waitForEvent' && overloads.length > 1) {
    const events = overloads.map((o) => o.params[0].type.replace(/^'(.*)'$/, '"$1"')).filter((t) => /^"/.test(t));
    const merged = { ...first, summary: 'Waits for the named event and returns its payload.', params: [{ ...first.params[0], type: events.join('|'), full: true }, { name: 'options', optional: true, rest: false, type: '', options: [{ name: 'predicate', optional: true, type: 'function' }, { name: 'timeout', optional: true, type: 'number' }] }], returns: 'the event payload' };
    return [lineOf(merged, tier)];
  }
  const shown = overloads.slice(0, 2);
  return shown.map((member, index) => lineOf(member, tier, index === shown.length - 1 && overloads.length > 2 ? ' (+' + (overloads.length - 2) + ' more overloads)' : ''));
}

function build() {
  const pin = JSON.parse(fs.readFileSync(path.join(runner, 'package.json'), 'utf8')).dependencies.playwright;
  const core = version(path.join(runner, 'node_modules/playwright-core/package.json'));
  const full = version(path.join(runner, 'node_modules/playwright/package.json'));
  if (pin !== core || pin !== full) fail('Playwright pin ' + pin + ' differs from installed playwright-core ' + core + ' / playwright ' + full);

  const groups = kept(readMembers());
  const bySection = new Map(SECTIONS.map((section) => [section.id, []]));
  const unassigned = [];
  for (const [key, overloads] of groups) {
    const first = overloads[0];
    const section = sectionOf(first.iface, first.name);
    if (!section) unassigned.push(key);
    else bySection.get(section.id).push(overloads);
  }
  if (unassigned.length) fail('members in no section (extend SECTIONS): ' + unassigned.join(', '));

  const sections = SECTIONS.map((section) => {
    const lines = bySection.get(section.id).flatMap((overloads) => linesOf(overloads, section.tier));
    return { ...section, lines, names: bySection.get(section.id).map((o) => receiverOf(o[0].iface) + '.' + o[0].name), body: lines.join('\n') + '\n' };
  });
  const coreBytes = sections.filter((s) => s.tier === 'core').reduce((sum, s) => sum + Buffer.byteLength(s.body), 0);
  if (coreBytes > CORE_CAP) fail('core sections are ' + coreBytes + ' bytes, cap ' + CORE_CAP);
  for (const section of sections) {
    if (!section.lines.length) fail('empty section ' + section.id);
    if (section.tier === 'extended' && Buffer.byteLength(section.body) > EXTENDED_CAP) {
      fail('section ' + section.id + ' is ' + Buffer.byteLength(section.body) + ' bytes, cap ' + EXTENDED_CAP);
    }
  }

  const out = [];
  out.push('# playwright-reference format=1 playwright=' + pin);
  out.push('# types.d.ts sha256=' + sha256(fs.readFileSync(TYPES)));
  out.push('# test.d.ts sha256=' + sha256(fs.readFileSync(TEST_TYPES)));
  out.push('@@preamble');
  out.push('Playwright ' + pin + ' API reference, generated from the pinned type definitions. It is guidance, not an allow-list: any Playwright API may be used.');
  out.push('Each line is receiver.member(params) -> result  # summary. Option bags are shown as names with ? when optional (core) or name: type (extended).');
  out.push('@@index');
  for (const section of sections) {
    out.push(section.id + ' (' + section.tier + ') ' + section.title + ': ' + section.names.join(', '));
  }
  for (const section of sections) {
    out.push('@@section ' + section.id + ' ' + section.tier + ' ' + section.title);
    out.push(section.body.replace(/\n$/, ''));
  }
  return Buffer.from(out.join('\n') + '\n', 'utf8');
}

const generated = build();
const mode = process.argv[2];
if (mode === '--hash') {
  console.log(sha256(generated));
} else if (mode === '--check') {
  const current = fs.existsSync(OUTPUT) ? fs.readFileSync(OUTPUT) : Buffer.alloc(0);
  if (!current.equals(generated)) fail('the committed reference differs from the generated one; run node tools/build-playwright-reference.cjs');
} else if (mode === undefined) {
  fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
  fs.writeFileSync(OUTPUT, generated);
  console.log(OUTPUT + ' ' + generated.length + ' bytes sha256=' + sha256(generated));
} else {
  fail('unknown option ' + mode);
}
